use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/finalize-drain-bundle176";fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn main(){assert_eq!(read(r("native/result.json"))["status"],"complete");let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("build-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}for(p,h)in read(r("frozen-candidate.json"))["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().into());}for f in["link.rs","link-helper","frozen-candidate.json","frozen-candidate-cargo.jsonl","driver.rs","support/perf.rs"]{let p=r(f);pins.insert(p.display().to_string(),hash(p));}fs::write(r("link-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r("link-plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r("link-pins.json"),"steps":[{"kind":"link-sdk","name":"sdk","artifacts":r("frozen-candidate-cargo.jsonl"),"driver":r("driver.rs"),"additional_sources":[r("support/perf.rs")],"timeout_seconds":1800}]})).unwrap()).unwrap();}
